handler.function:
console.log('\n' + '='.repeat(80));
console.log('🔍 [ResearchExecution] Research execution server started');
console.log('='.repeat(80));

const messages = state.messages || [];
const lastMessage = messages[messages.length - 1];

// ★Check if tool result already exists
const hasToolResult = messages.some(msg => {
  return (
    msg.role === 'tool' ||
    msg.constructor?.name === 'ToolMessage' ||
    msg.type === 'tool' ||
    (msg.lc_namespace && Array.isArray(msg.lc_namespace) && msg.lc_namespace.includes('tool'))
  );
});

console.log('\n📊 State check:');
console.log('  Total messages:', messages.length);
console.log('  Has tool result:', hasToolResult);

let userContent = '';

// Find first user message
for (const msg of messages) {
  if (msg.role === 'user' && msg.content) {
    userContent = msg.content;
    break;
  }
}

console.log('  Original task length:', userContent.length, 'chars');

if (!userContent || userContent.length === 0) {
  console.error('❌ Task description is empty');
  return {
    messages: [
      {
        role: 'assistant',
        content: JSON.stringify({
          result: {
            researchResults: [],
            summary: 'Error: Task description not found'
          }
        })
      }
    ]
  };
}

try {
  let response;

  if (!hasToolResult) {
    // ★First time: Request tool call
    console.log('\n🔎 [First] Requesting web search');

    const researchPrompt = `Please conduct detailed research on the following task using the web search tool (mcp__tavily-mcp__tavily-search):

${userContent}

Instructions:
1. Prioritize searches in Japanese
2. Execute search only once
3. Record URLs from search results

Be sure to use the mcp__tavily-mcp__tavily tool only once to retrieve information.`;

    response = await model.invoke([
      { role: 'user', content: researchPrompt }
    ]);
  } else {
    // ★Second time: Generate final answer using tool results
    console.log('\n📝 [Second] Analyzing tool results to generate final answer');

    // Pass entire message history to LLM
    response = await model.invoke(messages);
  }

  console.log('\n🤖 LLM response received');
  console.log('  Response type:', typeof response);
  console.log('  Has tool_calls:', !!response.tool_calls);
  if (response.tool_calls && response.tool_calls.length > 0) {
    console.log('  Tool calls count:', response.tool_calls.length);
    response.tool_calls.forEach((tc, idx) => {
      console.log(`  [${idx + 1}] ${tc.name}`);
    });
  } else if (response.content) {
    console.log('  Content length:', response.content.length, 'chars');
  }

  return {
    messages: [response]
  };
} catch (error) {
  console.error('❌ Research execution error:', error.message);
  console.error('  Stack:', error.stack);
  return {
    messages: [
      {
        role: 'assistant',
        content: `An error occurred during research: ${error.message}`
      }
    ]
  };
}

console.log('\n📋 [result_formatter] Starting research result formatting');

const messages = state.messages || [];
let toolResults = [];
let llmResponse = '';

// Debug: Check message structure
console.log('  Total messages:', messages.length);
if (messages.length > 0) {
  console.log('  Last 3 messages:');
  for (let i = Math.max(0, messages.length - 3); i < messages.length; i++) {
    const msg = messages[i];
    console.log(`    [${i}] type=${msg.constructor?.name || typeof msg}, role=${msg.role}, hasContent=${!!msg.content}`);
  }
}

// Collect tool execution results and LLM responses
for (let i = messages.length - 1; i >= 0; i--) {
  const msg = messages[i];

  // ★Improvement: Extended ToolMessage detection
  const isToolMessage = (
    msg.role === 'tool' ||
    msg.constructor?.name === 'ToolMessage' ||
    msg.type === 'tool' ||
    (msg.lc_namespace && msg.lc_namespace.includes('tool'))
  );

  if (isToolMessage) {
    console.log(`  ✓ Found tool message at index ${i}`);
    toolResults.unshift(msg.content);
  } else if (msg.constructor?.name === 'AIMessage') {
    // ★For AIMessage, record as LLM response if content exists
    if (msg.content && typeof msg.content === 'string' && msg.content.length > 0) {
      console.log(`  ✓ Found AI response at index ${i}, length:`, msg.content.length);
      llmResponse = msg.content;
      break;
    }
  } else if (msg.role === 'assistant' && msg.content && typeof msg.content === 'string') {
    console.log(`  ✓ Found assistant response at index ${i}`);
    llmResponse = msg.content;
    break;
  }
}

console.log('  Tool results count:', toolResults.length);
console.log('  LLM response length:', llmResponse.length, 'chars');

// Display tool result summary
if (toolResults.length > 0) {
  console.log('  Tool results preview:');
  toolResults.slice(0, 3).forEach((result, idx) => {
    const preview = typeof result === 'string' ? result.substring(0, 100) : JSON.stringify(result).substring(0, 100);
    console.log(`    [${idx}] ${preview}...`);
  });
}

// Building research results
const lastMessage = messages[messages.length - 1];
let userContent = '';

// Find original task description
for (const msg of messages) {
  if (msg.role === 'user' && msg.content) {
    userContent = msg.content;
    break;
  }
}

let findings = '';
const sources = [];

// Extract URLs from tool results
for (const result of toolResults) {
  try {
    const parsed = typeof result === 'string' ? JSON.parse(result) : result;
    if (parsed.results && Array.isArray(parsed.results)) {
      parsed.results.forEach(r => {
        if (r.url) sources.push(r.url);
      });
    }
  } catch (e) {
    // Ignore JSON parse failures
  }
}

// ★Improvement: Consider both tool results and LLM responses
if (toolResults.length === 0 && llmResponse) {
  // When LLM responds directly (no tools)
  findings = llmResponse;
  console.log('  ✓ Using LLM direct response');
} else if (toolResults.length > 0) {
  // ★If no LLM final response, use tool results directly
  if (!llmResponse || llmResponse.length === 0) {
    // Summarize tool results concisely
    findings = `Research conducted from the following sources:\n\n${toolResults.slice(0, 3).map((r, i) => `${i+1}. ${typeof r === 'string' ? r.substring(0, 200) : JSON.stringify(r).substring(0, 200)}...`).join('\n\n')}`;
    console.log('  ⚠️ No LLM response, using tool results directly');
  } else {
    findings = llmResponse;
    console.log('  ✓ Using LLM final response');
  }
} else {
  findings = 'No research results';
  console.log('  ⚠️ No tool results or LLM responses');
}

const researchResult = {
  taskId: 1,
  objective: userContent.substring(0, 100) + (userContent.length > 100 ? '...' : ''),
  findings: findings || 'No research results',
  sources: sources.slice(0, 10), // Maximum 10 items
  completionStatus: findings ? 'completed' : 'error'
};

const result = {
  result: {
    researchResults: [researchResult],
    summary: researchResult.completionStatus === 'completed' ? 'Research completed' : 'An error occurred during research'
  }
};

console.log('\n📊 Research completed');
console.log('  Status:', researchResult.completionStatus);
console.log('  Findings length:', researchResult.findings.length, 'chars');
console.log('  Sources count:', researchResult.sources.length);
console.log('='.repeat(80) + '\n');

return {
  messages: [
    {
      role: 'assistant',
      content: JSON.stringify(result, null, 2)
    }
  ]
};

try {
  const lastMessage = state.messages[state.messages.length - 1];

  console.log('\n🔀 [needsTools] Condition evaluation');
  console.log('  Total messages:', state.messages.length);

  // ★Count number of tool execution results (ToolMessage)
  const toolResultCount = state.messages.filter(msg => {
    return (
      msg.role === 'tool' ||
      msg.constructor?.name === 'ToolMessage' ||
      msg.type === 'tool' ||
      (msg.lc_namespace && Array.isArray(msg.lc_namespace) && msg.lc_namespace.includes('tool'))
    );
  }).length;

  console.log('  Tool result count:', toolResultCount);

  // ★End if tool execution result already exists
  if (toolResultCount >= 1) {
    console.log('  ✓ Tool execution result exists (', toolResultCount, 'items), to result_formatter');
    return 'result_formatter';
  }

  // ★First tool call (tool_calls exist but not yet executed)
  if (
    lastMessage &&
    typeof lastMessage === 'object' &&
    lastMessage.tool_calls &&
    Array.isArray(lastMessage.tool_calls) &&
    lastMessage.tool_calls.length > 0
  ) {
    console.log('  ✓ Tool call detected (first time), to tools node');
    return 'tools';
  }

  console.log('  ✓ No tool needed, to result_formatter');
  return 'result_formatter';
} catch (error) {
  console.error('🔀 [needsTools] Error:', error);
  return 'result_formatter';
}
